#!/usr/bin/env python3
"""Compare SCOPe evidence without guessing when required records are missing."""

import argparse
import hashlib
import json
import re
import sys
import time
from pathlib import Path
from urllib.error import HTTPError, URLError
from urllib.parse import quote
from urllib.request import Request, urlopen


DEFAULT_BASE_URL = "https://scop.berkeley.edu/api/v1"
SCCS_RE = re.compile(r"^[a-z](?:\.[0-9]+){0,3}$")
PDB_RE = re.compile(r"^[0-9][A-Za-z0-9]{3}$")
HOMOLOGY_LEVELS = {"fa", "sf"}
ANCESTOR_CAVEAT_LEVELS = {"cf", "sf", "fa"}
RETRYABLE_STATUS = {429, 500, 502, 503, 504}
ANNOTATION_CAVEAT_FIELDS = ("comments", "inconsistencies", "repeats")
HOMOLOGY_CAVEAT_FIELDS = ("warnings", "heterogeneity")
RELATIONSHIP_VERDICTS = {
    "shared_family": {
        "scop_supports": (
            "close SCOPe relationship through the shared family; homology is "
            "implied unless a retrieved caveat qualifies that node"
        ),
        "scop_does_not_support": [
            "exact substrate identity",
            "exact reaction chemistry",
            "ligand specificity",
            "regulatory role",
            "oligomeric state",
            "whole-protein function",
            "interchangeable template use",
        ],
    },
    "shared_superfamily": {
        "scop_supports": "probable common ancestry through the shared superfamily",
        "scop_does_not_support": [
            "same-family relationship",
            "exact substrate identity",
            "exact reaction chemistry",
